INSERT INTO `book` VALUES (1,'Effective Java','Joshua Bloch','https://covers.openlibrary.org/b/id/8231856-L.jpg',2018,'9780134685991','OL25428908M','围绕 Java 语言设计、对象创建、泛型与并发的经典实践指南。','Java,后端,经典',1,'2026-06-11 15:01:18','2026-06-12 09:19:45',0,NULL,NULL),(2,'Clean Code','Robert C. Martin','https://covers.openlibrary.org/b/id/9610928-L.jpg',2008,'9780132350884','OL10909569M','以代码可读性、命名、函数和边界设计为核心的软件工程入门书。','工程,重构',1,'2026-06-11 15:01:18','2026-06-12 09:17:27',0,NULL,NULL),(3,'Designing Data-Intensive Applications','Martin Kleppmann','https://covers.openlibrary.org/b/id/9251996-L.jpg',2017,'9781449373320','OL26442158M','面向分布式系统、存储引擎和数据一致性的系统设计读物。','架构,数据库',1,'2026-06-11 15:01:18','2026-06-12 09:19:57',0,NULL,NULL),(4,'The Pragmatic Programmer','Andrew Hunt / David Thomas','https://covers.openlibrary.org/b/id/10476739-L.jpg',2019,'9780135957059','OL28157137M','强调持续反馈、自动化和工程判断力的通用开发方法论。','工程,方法论',0,'2026-06-11 15:01:18','2026-06-11 15:07:01',1,NULL,NULL),(5,'Codex Testing Book Updated','OpenAI','',2026,'TEST-20260611','LOCAL-CODEX-TEST','Smoke test book updated','手动录入',1,'2026-06-11 15:08:09','2026-06-11 15:08:09',1,NULL,NULL),(6,'Codex Testing Book Updated','OpenAI','',2026,'TEST-20260611','LOCAL-CODEX-TEST','Smoke test book updated','手动录入',1,'2026-06-11 15:10:47','2026-06-11 15:10:48',1,NULL,NULL),(7,'国家为什么会失败-德隆·阿西莫格鲁','','',0,'','','本地 PDF 文件上传，可在后台继续补充作者、出版年份和简介。','本地文件,PDF',1,'2026-06-12 10:20:19','2026-06-12 10:20:19',0,'db:7','PDF');
