INSERT INTO `note` VALUES (1,2,1,'为什么优先考虑静态工厂方法','静态工厂方法不仅能表达语义，还能控制实例缓存与返回子类型。','2026-06-09 21:32:00','2026-06-09 21:32:00',0),(2,4,1,'避免创建不必要对象的实践','在热点路径上减少装箱和临时对象分配，对吞吐和 GC 都很关键。','2026-06-10 08:45:00','2026-06-10 08:45:00',0),(3,3,2,'好命名降低维护成本','命名是最廉价、收益最高的维护动作，尤其在多人协作项目里。','2026-06-07 14:26:00','2026-06-07 14:26:00',0),(4,5,3,'日志、指标、追踪是不同维度','三者并不互相替代，系统观测能力要围绕问题定位链路来设计。','2026-06-05 20:12:00','2026-06-05 20:12:00',0),(5,2,1,'对象创建方式的取舍','Builder 更适合参数多且含可选参数的对象，既避免 telescoping constructor，也保留可读性。','2026-06-10 21:10:00','2026-06-10 21:10:00',0),(6,2,3,'复制与一致性的平衡','同一套数据模型，在复制拓扑变化后，吞吐和一致性承诺会同时变化。','2026-06-11 08:40:00','2026-06-11 08:40:00',0),(7,2,5,'Smoke Note','Smoke note content','2026-06-11 15:08:09','2026-06-11 15:08:09',1),(8,2,1,'Check Note','Check Content','2026-06-11 15:08:27','2026-06-11 15:08:27',1),(9,2,6,'Smoke Note Updated','Smoke note content updated','2026-06-11 15:10:47','2026-06-11 15:10:48',1);
INSERT INTO `comment` VALUES (1,3,1,'你的笔记写得太好了，深有同感！','2026-06-10 10:00:00','2026-06-10 10:00:00',0),(2,1,1,'这部分非常适合继续展开成对象创建章节总结。','2026-06-10 10:15:00','2026-06-10 10:15:00',0),(3,2,3,'命名这块确实是最容易被低估的基本功。','2026-06-08 09:20:00','2026-06-08 09:20:00',0),(4,1,7,'Smoke comment','2026-06-11 15:08:09','2026-06-11 15:08:09',1),(5,1,9,'Smoke comment','2026-06-11 15:10:48','2026-06-11 15:10:48',1);
